<?php if (!defined('ABSPATH')) { exit; } get_header(); $nh_archive = get_queried_object(); $nh_formats = nh_formats(); $nh_archive_title = is_category() && isset($nh_formats[$nh_archive->slug]) ? $nh_formats[$nh_archive->slug] : get_the_archive_title(); ?>
<main id="main-content" class="container archive-main"><header class="archive-header"><span class="eyebrow">JELAJAHI TULISAN</span><h1><?php echo esc_html($nh_archive_title); ?></h1><?php if (get_the_archive_description()) : ?><div class="archive-description"><?php echo wp_kses_post(get_the_archive_description()); ?></div><?php endif; ?></header>
<?php if (have_posts()) : ?><div class="article-grid"><?php while (have_posts()) : the_post(); get_template_part('template-parts/card'); endwhile; ?></div><?php the_posts_pagination(array('prev_text'=>'← Sebelumnya','next_text'=>'Berikutnya →')); else : ?><div class="empty-state"><h2>Ruang ini segera terisi.</h2><p>Belum ada artikel pada bentuk tulisan ini. Jelajahi tulisan lainnya di beranda.</p><a class="read-link" href="<?php echo esc_url(home_url('/')); ?>">Kembali ke beranda ↗</a></div><?php endif; ?></main><?php get_footer(); ?>
